package com.diagnostics.lab.controller;

import com.diagnostics.lab.entity.LabOrder;
import com.diagnostics.lab.repository.LabOrderRepository;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/lab-orders")
public class LabResultsController {

    private final LabOrderRepository labOrderRepository;

    public LabResultsController(LabOrderRepository labOrderRepository) {
        this.labOrderRepository = labOrderRepository;
    }

    @GetMapping("/{orderId}/report")
    @PreAuthorize("hasRole('CLINIC_STAFF') or @orderSecurityService.isPatientOwner(#orderId, authentication.name)")
    public ResponseEntity<String> viewDiagnosticReport(@PathVariable Long orderId) {
        LabOrder order = labOrderRepository.findById(orderId)
                .orElseThrow(() -> new IllegalArgumentException("Order not found"));
        return ResponseEntity.ok(order.getDetailedPathologyReport());
    }
}
